-- Patients of the vaccination centre. SYNTHETIC: generated by demo/lib/synthetic-patients.mjs, no real person.
-- The fiscal codes have the official shape but a wrong check letter, so none can belong to anyone.
CREATE TABLE patients (
  id          BIGINT AUTO_INCREMENT PRIMARY KEY,
  fiscal_code VARCHAR(16)  NOT NULL UNIQUE,
  last_name   VARCHAR(60)  NOT NULL,
  first_name  VARCHAR(60)  NOT NULL,
  sex         CHAR(1)      NOT NULL,
  birth_date  DATE         NOT NULL,
  birth_place VARCHAR(60)  NOT NULL,
  phone       VARCHAR(20),
  health_card VARCHAR(20)
);


ALTER TABLE patients ALTER COLUMN id RESTART WITH 31;
